<?php require __DIR__.'/app/bootstrap.php';$u=require_user();$iid=(int)($_GET['invoice']??0);$q=db()->prepare('SELECT * FROM invoices WHERE id=? AND user_id=?');$q->execute([$iid,$u['id']]);$i=$q->fetch();if(!$i){http_response_code(404);die('Invoice not found.');}if(!empty($i['mollie_payment_id'])){try{process_mollie_payment($i['mollie_payment_id']);}catch(Throwable $e){}}header('Location: /billing.php?payment_return=1');exit;
